def match_parens(lst):
    if len(lst) != 2 or not all(isinstance(s, str) for s in lst):
        return 'No'

    for s in lst:
        if not all(c in ['(', ')'] for c in s):
            return 'No'

    count = 0
    for s in lst:
        count += s.count('(') - s.count(')')
        if count < 0:
            return 'No'

    return 'Yes' if count == 0 else 'No'

